package com.bank.jsondb.service;
import com.bank.jsondb.model.Customer;
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class KycService {
    private static final Logger log = Logger.getLogger(KycService.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final List<Customer> customers;
    public KycService(List<Customer> customers) { this.customers = customers; }

    // jsonb containment: kyc @> {"status": value}
    public List<String> findByStatus(String status) {
        List<String> ids = customers.stream()
            .filter(c -> status.equals(c.getKyc().get("status")))
            .map(Customer::getId).collect(Collectors.toList());
        log.info(() -> "findByStatus(" + status + ") -> " + ids);
        return ids;
    }
    // kyc->>'key'
    public String extract(String id, String key) {
        return customers.stream().filter(c -> c.getId().equals(id)).findFirst()
            .map(c -> c.getKyc().get(key)).orElse(null);
    }
}
