package com.bank.jsondb;
import com.bank.jsondb.model.Customer;
import com.bank.jsondb.service.KycService;
import java.util.*;
import java.util.logging.*;

public class JsonDemo {
    public static void main(String[] args) {
        List<Customer> list = List.of(
            new Customer("SAV2001","Rajesh Kumar", Map.of("status","active","pan","ABCPK1234L","city","Delhi")),
            new Customer("CUR3001","Priya Sharma", Map.of("status","pending","gst","07AAAC","city","Delhi")));
        KycService svc = new KycService(list);
        System.out.println("active -> " + svc.findByStatus("active"));
        System.out.println("Rajesh city -> " + svc.extract("SAV2001","city"));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
